async function load(preferredRestaurantId){if(!token)return;try{data=await api("/bootstrap");$("auth").style.display="none";$("workspace").classList.add("show");$("who").textContent=data.user.name;render(preferredRestaurantId);api("/profile").then(p=>{if(p.avatar)$("userAvatar").innerHTML="<img alt=\"Profilbild\" src=\""+p.avatar+"\">"}).catch(console.error)}catch(x){console.error(x);localStorage.removeItem("bringness-pos-token");token=null}}
function render(preferredRestaurantId){let rs=data.restaurants;let previous=preferredRestaurantId||$("restaurant").value;$("restaurant").innerHTML=rs.length?rs.map(r=>'<option value="'+r.id+'">'+r.name+"</option>").join(""):'<option value="">Noch kein Betrieb</option>';if(previous&&rs.some(r=>r.id===previous))$("restaurant").value=previous;applyBusinessMode();let rid=$("restaurant").value||rs[0]?.id;let cs=data.categories.filter(x=>x.restaurantId===rid);$("categories").innerHTML='<button onclick="selectCat(\'all\')">Alle</button>'+cs.map(c=>'<button onclick="selectCat(\''+c.id+'\')">'+c.name+"</button>").join("");$("productCategory").innerHTML=cs.map(c=>'<option value="'+c.id+'">'+c.name+"</option>").join("");let ps=data.products.filter(x=>x.restaurantId===rid&&(cat==="all"||x.categoryId===cat));$("products").innerHTML=ps.length?ps.map(p=>'<div style="display:inline-flex;flex-direction:column;gap:4px"><button class="product" onclick="add(\''+p.id+'\')"><span class="pic">'+p.emoji+'</span><b>'+p.name+'</b><small>'+money(p.price)+'</small></button><button type="button" data-translate-product="'+p.id+'" data-translate-name="'+esc(p.name)+'">🌐 Übersetzungen</button><button type="button" data-label-product="'+p.id+'" data-label-name="'+esc(p.name)+'">ⓘ Allergene & Zusatzstoffe</button></div>').join(""):'<p class="muted">Lege unten Kategorien und Produkte an.</p>';$("products").querySelectorAll("[data-translate-product]").forEach(b=>b.onclick=()=>manageProductTranslations(b.dataset.translateProduct,b.dataset.translateName).catch(e=>alert(e.message)));$("products").querySelectorAll("[data-label-product]").forEach(b=>b.onclick=()=>manageProductLabels(b.dataset.labelProduct,b.dataset.labelName).catch(e=>alert(e.message)));renderCart()}
window.selectCat=x=>{cat=x;render()};window.add=id=>{let p=data.products.find(x=>x.id===id),i=cart.find(x=>x.id===id);i?i.qty++:cart.push({...p,qty:1});renderCart()};
