async function manageProductLabels(productId,productName){const [catalog,current]=await Promise.all([api("/product-labels"),api("/products/"+encodeURIComponent(productId)+"/labels")]);const choose=(title,list,selected)=>{const text=list.map((x,i)=>(i+1)+". "+x.name).join("\n"),raw=prompt(title+" für „"+productName+"“\n\nNummern mit Komma auswählen; leer = keine.\n\n"+text,list.map((x,i)=>selected.includes(x.code)?i+1:null).filter(Boolean).join(","));if(raw===null)return null;return [...new Set(raw.split(",").map(x=>Number(x.trim())-1).filter(n=>Number.isInteger(n)&&list[n]).map(n=>list[n].code))]};const allergens=choose("Allergene",catalog.allergens,current.allergens||[]);if(allergens===null)return;const additives=choose("Zusatzstoffe",catalog.additives,current.additives||[]);if(additives===null)return;await api("/products/"+encodeURIComponent(productId)+"/labels",{method:"PUT",body:JSON.stringify({allergens,additives})});alert("Allergene und Zusatzstoffe gespeichert.")}
async function manageProductTranslations(productId,productName){if(confirm("Für „"+productName+"“ automatisch aus Deutsch in alle Gastsprachen übersetzen?\n\nOK = automatisch kostenlos mit LibreTranslate\nAbbrechen = einzelne Sprache manuell bearbeiten")){try{const j=await api("/products/"+encodeURIComponent(productId)+"/translations/auto",{method:"POST",body:"{}"});return alert("Automatisch übersetzt: "+j.languages.join(", ")+". Der Gerichtname bleibt unverändert.")}catch(e){alert(e.message);return}}const langs=[["de","Deutsch"],["en","English"],["fr","Français"],["es","Español"],["it","Italiano"],["tr","Türkçe"],["el","Ελληνικά"],["nl","Nederlands"],["pl","Polski"]];let data=await api("/products/"+encodeURIComponent(productId)+"/translations"),existing=new Map((data.translations||[]).map(x=>[x.languageCode,x]));let lang=prompt("Übersetzung für "+productName+"\nSprachcode: "+langs.map(x=>x[0]+"="+x[1]).join(", "),"en");if(!lang)return;lang=lang.toLowerCase().split("-")[0];if(!langs.some(x=>x[0]===lang))return alert("Bitte einen unterstützten Sprachcode wählen.");const old=existing.get(lang)||{};const description=prompt("Beschreibung ("+lang+")",old.description||data.description||"");if(description===null)return;const ingredients=prompt("Zutaten ("+lang+")",old.ingredients||"");if(ingredients===null)return;const allergens=prompt("Allergene ("+lang+")",old.allergens||"");if(allergens===null)return;await api("/products/"+encodeURIComponent(productId)+"/translations",{method:"PUT",body:JSON.stringify({languageCode:lang,description,ingredients,allergens})});alert("Übersetzung gespeichert. Der Gerichtname bleibt unverändert.")}
$("pay").onclick=async()=>{if(!cart.length)return;let total=cart.reduce((s,x)=>s+x.qty*x.price,0);await api("/orders",{method:"POST",body:JSON.stringify({restaurantId:$("restaurant").value,items:cart.map(x=>({productId:x.id,name:x.name,qty:x.qty,price:x.price,tax:x.tax})),total,paymentMethod:$("paymentMethod").value})});cart=[];renderCart();$("saleMsg").textContent="Verkauf gespeichert und Beleg erstellt.";setTimeout(()=>$("saleMsg").textContent="",3000)};
