async function showModule(v){const restaurantId=$("restaurant").value;if(["tische","kueche","bestellungen"].includes(v)&&!isRestaurantMode()){v="kasse"};document.querySelectorAll("#mainnav button[data-view]").forEach(b=>b.classList.toggle("active",b.dataset.view===v));let k=$("kasseView"),m=$("moduleView"),man=document.querySelectorAll(".manage");if(v==="kasse"){k.style.display="block";m.classList.remove("show");man.forEach(x=>x.style.display="none");return}k.style.display="none";m.classList.add("show");man.forEach((x,i)=>x.style.display=((v==="artikel"&&i===0)||(v==="mitarbeiter"&&i===1))?"block":"none");let x=moduleInfo[v]||["Modul","",""];m.innerHTML=(v==="tische"?'<div id="moduleBody">Wird geladen…</div>':'<div class="eyebrow">Bringness POS</div><h2>'+x[0]+'</h2><p class="muted">'+x[1]+'</p><div id="moduleBody">Wird geladen…</div>');if(!restaurantId)return $("moduleBody").innerHTML='<div class="modulecard">Bitte zuerst einen Betrieb auswählen.</div>';try{if(v==="tische"){await renderTableDashboard(restaurantId);return}if(v==="einstellungen"){await renderRestaurantBranding(restaurantId);return}if(v==="lizenz"){await renderLicensing();return}if(v==="bestellungen"||v==="kueche"){await renderOrderBoard(v,restaurantId);return}let info=moduleInfo[v];$("moduleBody").innerHTML='<div class="modulegrid"><div class="modulecard"><b>'+info[1]+'</b><p class="muted">'+info[2]+'</p></div></div>'}catch(e){$("moduleBody").innerHTML='<div class="modulecard">Fehler: '+esc(e.message)+'</div>'}}

async function renderLicensing(){const b=$("moduleBody");b.innerHTML='<div class="modulecard">Lizenzdaten werden geladen…</div>';const [lic,stat]=await Promise.all([api("/licensing"),api("/billing/status")]);const plans=lic.plans||[],features=new Map((stat.features||[]).map(x=>[x.feature_code,x]));const wanted=[["pos_base_monthly","pos_base","Basis","Kasse und Grundfunktionen"],["restaurant_monthly","restaurant","Restaurant","Tische, Bestellungen, Küche und Service"],["table_qr_monthly","table_qr","Tisch-QR","QR-Bestellungen direkt vom Tisch"]];b.innerHTML='<div class="modulegrid">'+wanted.map(([code,feature,title,desc])=>{const p=plans.find(x=>x.code===code),f=features.get(feature),active=f&&f.status==="active"&&(!f.ends_at||new Date(f.ends_at)>new Date()||f.grace_until&&new Date(f.grace_until)>new Date()),grace=f?.grace_until&&new Date(f.grace_until)>new Date(),price=p?Number(p.amount_cents)/100:0;return '<div class="modulecard"><b>'+title+'</b><p class="muted">'+desc+'</p><div style="font-size:25px;font-weight:900">'+money(price)+' <small style="font-size:12px">netto / Monat + 19 % MwSt.</small></div><p><strong>Status:</strong> '+(active?(grace?'Nachfrist bis '+new Date(f.grace_until).toLocaleDateString("de-DE"):'Aktiv'):'Nicht aktiv')+'</p>'+(active?'<span class="muted">Zahlungsstatus: '+esc(f.payment_status||"ok")+'</span>':'<button class="pay" data-buy-plan="'+code+'">Jetzt aktivieren</button>')+'</div>'}).join("")+'</div><p class="muted" style="margin-top:14px">Nach erfolgreicher Mollie-Zahlung wird das gebuchte Modul automatisch freigeschaltet.</p>';b.querySelectorAll("[data-buy-plan]").forEach(btn=>btn.onclick=async()=>{btn.disabled=true;btn.textContent="Mollie wird geöffnet…";try{const j=await api("/billing/checkout",{method:"POST",body:JSON.stringify({planCode:btn.dataset.buyPlan})});if(!j.checkoutUrl)throw Error("Keine Zahlungsseite erhalten");location.href=j.checkoutUrl}catch(e){btn.disabled=false;btn.textContent="Jetzt aktivieren";alert(e.message)}})}
function updateConnectionStatus(online){const el=$("connectionStatus");if(!el)return;el.classList.toggle("online",online===true);el.classList.toggle("offline",online===false);el.classList.toggle("checking",online===null);el.querySelector(".connectionLabel").textContent=online===true?"Online":online===false?"Offline":"Prüfe Verbindung";el.title=online===true?"Bringness-Server und Datenbank erreichbar":online===false?"Bringness-Server oder Datenbank nicht erreichbar":"Verbindung wird geprüft"}
async function checkConnection(){if(!navigator.onLine){updateConnectionStatus(false);return}try{const controller=new AbortController(),timeout=setTimeout(()=>controller.abort(),5000);try{const r=await fetch("/health",{cache:"no-store",signal:controller.signal});if(!r.ok)throw Error("Server nicht erreichbar");const j=await r.json();updateConnectionStatus(j.status==="ok"&&j.database==="ok")}finally{clearTimeout(timeout)}}catch(e){updateConnectionStatus(false)}}
window.addEventListener("online",checkConnection);window.addEventListener("offline",()=>updateConnectionStatus(false));checkConnection();setInterval(checkConnection,30000);
