$("favoritesBtn").onclick=()=>{const key="bringness-pos-favorites",saved=JSON.parse(localStorage.getItem(key)||"[]");openAccount('<h3>Favoriten</h3><p class="muted">Schnellzugriffe auf diesem Gerät speichern.</p><div id="favoriteOptions"></div>');const options=[["kasse","Kasse"],["tische","Tische"],["bestellungen","Bestellungen"],["kueche","Küche"],["artikel","Artikel"],["mitarbeiter","Mitarbeiter"]];$("favoriteOptions").innerHTML=options.map(([v,n])=>'<label style="display:inline-flex;gap:5px;margin:8px"><input type="checkbox" data-favorite="'+v+'" '+(saved.includes(v)?"checked":"")+'>'+n+'</label>').join("")+'<div id="favoriteLinks"></div>';const update=()=>{$("favoriteLinks").innerHTML=JSON.parse(localStorage.getItem(key)||"[]").map(v=>'<button data-open-favorite="'+v+'">'+esc(options.find(x=>x[0]===v)?.[1]||v)+'</button>').join(" ");document.querySelectorAll("[data-open-favorite]").forEach(b=>b.onclick=()=>{panel.hidden=true;showModule(b.dataset.openFavorite)})};document.querySelectorAll("[data-favorite]").forEach(el=>el.onchange=()=>{localStorage.setItem(key,JSON.stringify([...document.querySelectorAll("[data-favorite]:checked")].map(x=>x.dataset.favorite)));update()});update()};


let tableDashboardPolling=false,tableDashboardSnapshot="",tableDashboardState=null;
async function renderTableDashboard(restaurantId){
 const body=$("moduleBody"),j=await api("/tables?restaurantId="+encodeURIComponent(restaurantId)),tables=j.tables||[];
 const statuses={free:"Frei",open:"Besetzt",kitchen:"In Küche",preparing:"In Zubereitung",ready:"Fertig",served:"Serviert",reserved:"Reserviert"};
 const state=t=>statuses[t.status]?t.status:"free";
 body.innerHTML='<div style="margin-bottom:14px"><button id="tableAdd" class="primary" type="button">＋ Tisch hinzufügen</button></div><div id="tableSections"></div><div class="tablelegend"><span style="--dot:#0ba45b">Frei</span><span style="--dot:#f47a18">Besetzt</span><span style="--dot:#2673e9">In Küche</span><span style="--dot:#8b45ce">Fertig</span><span style="--dot:#6b7888">Reserviert</span></div><div id="tableFeedback" role="status"></div>';
 tableDashboardSnapshot=JSON.stringify(tables);tableDashboardState={restaurantId,getState:()=>({})};
 const card=t=>{const status=state(t),count=Number(t.open_orders||0),amount=Number(t.open_total_cents||0),mins=t.first_order_at?Math.max(1,Math.floor((Date.now()-new Date(t.first_order_at).getTime())/60000)):0;return '<button class="tabletile '+status+'" data-table="'+esc(t.id)+'" aria-label="'+esc(t.name)+': '+statuses[status]+'">'+(count?'<span class="tablebadge">'+count+'</span>':"")+'<span class="tableicon" aria-hidden="true"><svg viewBox="0 0 60 44" width="42" height="33" fill="currentColor"><circle cx="30" cy="9" r="6"/><circle cx="12" cy="13" r="5"/><circle cx="48" cy="13" r="5"/><path d="M19 39v-9c0-7 4-12 11-12s11 5 11 12v9H19ZM1 39v-8c0-7 4-12 11-12 3 0 6 1 8 4-2 3-3 6-3 10v6H1Zm42 0v-6c0-4-1-7-3-10 2-3 5-4 8-4 7 0 11 5 11 12v8H43Z"/></svg></span><b>'+esc(t.name)+'</b><small>● '+statuses[status]+'</small>'+(mins?'<span class="tablemeta">'+mins+' min · '+count+' Bestellungen</span>':"")+'<span class="tableaction">Tisch öffnen →</span><span class="tableamount"><span>Offener Betrag</span><strong>'+euro(amount)+'</strong></span></button>'};
 const groups=[...new Set(tables.map(t=>t.area||"Innen"))];
 $("tableSections").innerHTML=groups.map(area=>{const rows=tables.filter(t=>(t.area||"Innen")===area);return '<section class="tablearea"><div class="tableareahead"><h3>⌂ '+esc(area)+' <span class="muted">('+rows.length+')</span></h3></div><div class="tableplan">'+rows.map(card).join("")+'</div></section>'}).join("")||'<div class="tableempty">Keine Tische vorhanden.</div>';
 $("tableSections").querySelectorAll("[data-table]").forEach(el=>el.onclick=()=>{const t=tables.find(x=>x.id===el.dataset.table);if(t)openTableDetails(t,restaurantId).catch(e=>{$("tableFeedback").textContent=e.message})});
 $("tableAdd").onclick=()=>showAddTableForm(restaurantId);
}
function showAddTableForm(restaurantId){
 const host=$("tableFeedback");
 host.innerHTML='<div class="tabledetail"><h3>Tisch hinzufügen</h3><input id="newTableName" placeholder="Tischname, z. B. 5" maxlength="80"><input id="newTableArea" placeholder="Bereich" value="Innen" maxlength="80"><div class="tabledetailactions"><button id="saveNewTable" class="primary">＋ Tisch hinzufügen</button><button id="cancelNewTable">Abbrechen</button></div></div>';
 $("cancelNewTable").onclick=()=>host.innerHTML="";
 $("saveNewTable").onclick=async()=>{const name=$("newTableName").value.trim(),area=$("newTableArea").value.trim()||"Innen";if(!name)return alert("Bitte Tischname eingeben.");try{await api("/tables",{method:"POST",body:JSON.stringify({restaurantId,name,area})});await renderTableDashboard(restaurantId)}catch(e){alert(e.message)}};
}
async function openTableDetails(t,restaurantId){
 const host=$("tableFeedback"),j=await api("/tables/"+encodeURIComponent(t.id)+"/details"),orders=j.orders||[],open=orders.filter(o=>!["paid","cancelled"].includes(o.status)),amount=open.reduce((sum,o)=>sum+Number(o.total_cents||0),0);
 host.innerHTML='<div class="tabledetail"><h3>'+esc(t.name)+' · '+esc(t.area||"Innen")+'</h3><p>'+open.length+' offene Bestellungen · <b>'+euro(amount)+'</b> offen</p><div class="tabledetailactions"><button class="primary" data-table-action="order">＋ Bestellung aufnehmen</button><button data-table-action="settle" >Tisch abrechnen</button><button data-table-action="addtable">＋ Tisch hinzufügen</button><button data-table-action="qr">▦ Tisch-QR</button><button data-table-action="delete" >🗑 Tisch löschen</button><button data-table-action="open">Besetzt</button><button data-table-action="reserved">Reserviert</button><button data-table-action="free" '+(open.length?'disabled title="Offene Bestellungen zuerst abschließen"':'')+'>Freigeben</button><button data-table-action="close">Schließen</button></div><div id="tableOrderDetails">'+(orders.length?orders.map(o=>'<div class="tableorder"><b>Bestellung #'+esc(o.id.slice(0,8))+' · '+euro(o.total_cents)+'</b><br><small>'+esc(o.status)+' · '+new Date(o.created_at).toLocaleString("de-DE")+'</small><p>'+o.items.map(i=>esc(i.quantity)+' × '+esc(i.name)).join("<br>")+'</p></div>').join(""):'<p class="muted">Noch keine Bestellungen für diesen Tisch.</p>')+'</div><p class="muted">Gastbestellungen über den Tisch-QR erscheinen automatisch in der Bestellübersicht und können am Tisch abgerechnet werden.</p></div>';
 host.scrollIntoView({behavior:"smooth",block:"nearest"});
 host.querySelectorAll("[data-table-action]").forEach(b=>b.onclick=async()=>{if(b.dataset.tableAction==="close"){host.innerHTML="";return}if(b.dataset.tableAction==="order"){showTableOrderForm(t,restaurantId,host);return}if(b.dataset.tableAction==="settle"){showTableSettlement(t,restaurantId,host,open,amount);return}if(b.dataset.tableAction==="addtable"){showAddTableForm(restaurantId);return}if(b.dataset.tableAction==="qr"){showTableQr(t,host);return}if(b.dataset.tableAction==="delete"){if(open.length){host.querySelector(".tabledetail>p").textContent="Tisch hat offene Bestellungen. Bitte zuerst abrechnen oder verschieben.";return}if(!confirm("Tisch "+t.name+" wirklich löschen? Der QR-Code wird ungültig. Bezahlte Bestellungen und Belege bleiben erhalten."))return;b.disabled=true;try{await api("/tables/"+encodeURIComponent(t.id),{method:"DELETE"});await renderTableDashboard(restaurantId);$("tableFeedback").textContent="Tisch "+t.name+" wurde gelöscht."}catch(e){host.querySelector(".tabledetail>p").textContent=e.message;b.disabled=false}return}try{await api("/tables/"+encodeURIComponent(t.id)+"/status",{method:"PATCH",body:JSON.stringify({status:b.dataset.tableAction})});await renderTableDashboard(restaurantId)}catch(e){host.querySelector(".tabledetail>p").textContent=e.message}});
}

function showTableOrderForm(t,restaurantId,host){
 const products=data.products.filter(p=>p.restaurantId===restaurantId),selection=new Map();
 const detail=host.querySelector(".tabledetail");if(!detail)return;
 let existing=detail.querySelector("#tableOrderForm");if(existing)existing.remove();
 const section=document.createElement("section");section.id="tableOrderForm";section.className="tableorderform";
 section.innerHTML='<h3>Bestellung für Tisch '+esc(t.name)+'</h3><p class="muted">Artikel auswählen und Mengen festlegen. Die Bestellung bleibt zunächst offen und unbezahlt.</p><div id="tableProductChoices">'+(products.length?products.map(p=>'<div class="tableproduct"><span>'+esc(p.name)+' <small>'+money(p.price)+'</small></span><button type="button" data-product-add="'+esc(p.id)+'">＋</button></div>').join(""):'<p>Für diesen Betrieb sind noch keine Artikel angelegt.</p>')+'</div><div id="tableOrderCart" class="muted">Noch keine Artikel ausgewählt.</div><div class="tabledetailactions"><button class="primary" id="submitTableOrder" disabled>Bestellung an Küche senden</button><button id="cancelTableOrder">Abbrechen</button></div><p id="tableOrderMessage" role="status"></p>';
 detail.insertBefore(section,detail.querySelector("#tableOrderDetails"));
 const refresh=()=>{let total=0;const rows=[...selection].map(([id,qty])=>{const p=products.find(z=>z.id===id);total+=p.price*qty;return '<div class="tableproduct"><span>'+esc(p.name)+' · '+qty+' × '+money(p.price)+'</span><button type="button" data-product-minus="'+esc(id)+'">−</button></div>'});section.querySelector("#tableOrderCart").innerHTML=rows.join("")+'<b>Summe: '+money(total)+'</b>';section.querySelector("#submitTableOrder").disabled=!selection.size;section.querySelectorAll("[data-product-minus]").forEach(b=>b.onclick=()=>{const id=b.dataset.productMinus,qty=selection.get(id)||0;if(qty<=1)selection.delete(id);else selection.set(id,qty-1);refresh()})};
 section.querySelectorAll("[data-product-add]").forEach(b=>b.onclick=()=>{const id=b.dataset.productAdd;selection.set(id,Math.min(99,(selection.get(id)||0)+1));refresh()});
 section.querySelector("#cancelTableOrder").onclick=()=>section.remove();
 section.querySelector("#submitTableOrder").onclick=async()=>{const btn=section.querySelector("#submitTableOrder");btn.disabled=true;try{await api("/tables/order",{method:"POST",body:JSON.stringify({tableId:t.id,items:[...selection].map(([productId,qty])=>({productId,qty}))})});await renderTableDashboard(restaurantId);const current=$("tableFeedback");current.textContent="Bestellung für Tisch "+t.name+" gespeichert und an die Küche übergeben.";current.scrollIntoView({behavior:"smooth",block:"nearest"})}catch(e){section.querySelector("#tableOrderMessage").textContent=e.message;btn.disabled=false}};
 refresh();section.scrollIntoView({behavior:"smooth",block:"nearest"});
}

function showTableSettlement(t,restaurantId,host,orders,amount){
 const detail=host.querySelector(".tabledetail");if(!detail)return;
 detail.querySelector("#tableSettlement")?.remove();
 const section=document.createElement("section");section.id="tableSettlement";section.className="tableorderform";
 section.innerHTML='<h3>Tisch '+esc(t.name)+' abrechnen</h3><p>'+orders.length+' offene Bestellungen · <b>'+euro(amount)+'</b></p><label for="tablePaymentMethod">Zahlungsart</label><select id="tablePaymentMethod"><option value="cash">Bar</option><option value="card">Karte (bereits extern bezahlt)</option></select><p class="muted">Bei Karte erst die Zahlung am Terminal bestätigen. Diese Funktion belastet keine Karte und erstellt noch keinen fiskalisierten Beleg.</p><div class="tabledetailactions"><button class="primary" id="confirmTablePayment" '+(!orders.length?'disabled':'')+'>Zahlung verbuchen und Tisch freigeben</button><button id="cancelTablePayment">Abbrechen</button></div><p id="tablePaymentMessage" role="status"></p>';
 detail.insertBefore(section,detail.querySelector("#tableOrderDetails"));
 section.querySelector("#cancelTablePayment").onclick=()=>section.remove();
 section.querySelector("#confirmTablePayment").onclick=async()=>{const btn=section.querySelector("#confirmTablePayment");btn.disabled=true;try{const result=await api("/tables/settle",{method:"POST",body:JSON.stringify({tableId:t.id,paymentMethod:section.querySelector("#tablePaymentMethod").value})});await renderTableDashboard(restaurantId);$("tableFeedback").textContent=result.paidOrders+" Bestellungen über "+euro(result.totalCents)+" verbucht. Tisch "+t.name+" ist frei. Belegnummern: "+result.receiptNumbers.join(", ")}catch(e){section.querySelector("#tablePaymentMessage").textContent=e.message;btn.disabled=false}};
 section.scrollIntoView({behavior:"smooth",block:"nearest"});
}

async function showTableTransfer(t,restaurantId,host,orders){
 const detail=host.querySelector(".tabledetail");if(!detail)return;
 detail.querySelector("#tableTransfer")?.remove();
 const section=document.createElement("section");section.id="tableTransfer";section.className="tableorderform";
 section.innerHTML='<h3>Bestellungen von '+esc(t.name)+' verschieben</h3><p class="muted">Alle offenen Bestellungen werden auf einen freien Tisch desselben Betriebs übertragen. Bereits bezahlte Bestellungen bleiben am ursprünglichen Tisch.</p><div id="transferTargets">Freie Tische werden geladen …</div><p id="transferMessage" role="status"></p>';
 detail.insertBefore(section,detail.querySelector("#tableOrderDetails"));
 if(!orders.length){section.querySelector("#transferTargets").textContent="Dieser Tisch hat keine offenen Bestellungen.";return}
 try{const result=await api("/tables?restaurantId="+encodeURIComponent(restaurantId));const free=(result.tables||[]).filter(z=>z.id!==t.id&&z.status==="free"&&Number(z.open_orders||0)===0);
 section.querySelector("#transferTargets").innerHTML=free.length?'<label for="transferTarget">Zieltisch</label><select id="transferTarget">'+free.map(z=>'<option value="'+esc(z.id)+'">'+esc(z.name)+' · '+esc(z.area||"Innen")+'</option>').join("")+'</select><div class="tabledetailactions"><button class="primary" id="confirmTableTransfer">Bestellungen verschieben</button><button id="cancelTableTransfer">Abbrechen</button></div>':'<p>Kein freier Zieltisch verfügbar.</p><button id="cancelTableTransfer">Schließen</button>';
 section.querySelector("#cancelTableTransfer").onclick=()=>section.remove();
 section.querySelector("#confirmTableTransfer")?.addEventListener("click",async()=>{const btn=section.querySelector("#confirmTableTransfer"),target=section.querySelector("#transferTarget").value,name=free.find(z=>z.id===target)?.name||"Zieltisch";btn.disabled=true;try{const result=await api("/tables/transfer",{method:"POST",body:JSON.stringify({fromTableId:t.id,toTableId:target})});await renderTableDashboard(restaurantId);$("tableFeedback").textContent=result.movedOrders+" offene Bestellungen von "+t.name+" nach "+name+" verschoben."}catch(e){section.querySelector("#transferMessage").textContent=e.message;btn.disabled=false}});
 }catch(e){section.querySelector("#transferTargets").textContent=e.message}
 section.scrollIntoView({behavior:"smooth",block:"nearest"});
}

async function showTableQr(t,host){
 const detail=host.querySelector(".tabledetail");if(!detail)return;detail.querySelector("#tableQr")?.remove();
 const section=document.createElement("section");section.id="tableQr";section.className="tableorderform";section.innerHTML='<h3>QR-Code · '+esc(t.name)+'</h3><p id="tableQrStatus">QR-Code wird geladen …</p><div id="tableQrContent"></div>';detail.insertBefore(section,detail.querySelector("#tableOrderDetails"));
 try{const j=await api("/tables/"+encodeURIComponent(t.id)+"/qr");section.querySelector("#tableQrStatus").textContent="Diesen Code am Tisch aufstellen. Gäste öffnen damit die Speisekarte und bestellen direkt an diesen Tisch.";section.querySelector("#tableQrContent").innerHTML='<div class="qrposterpreview"><h2>'+esc(j.restaurantName||"Restaurant")+'</h2><p>Speisekarte öffnen und am Tisch bestellen</p><div class="qrposterimage">'+j.svg+(j.logo?'<img src="'+esc(j.logo)+'" alt="Restaurantlogo">':"")+'</div><div class="qrpostersteps"><span>① QR-Code scannen</span><span>② Speisekarte ansehen</span><span>③ Bestellung aufgeben</span></div><strong class="qrpostertable">'+esc(j.tableName||t.name)+'</strong></div><div class="tabledetailactions"><button id="printTableQr" class="primary">Druckvorlage öffnen</button><button id="copyTableQr">Link kopieren</button><button id="resetTableQr">QR-Code erneuern</button></div><p id="tableQrMessage" role="status"></p>';
 section.querySelector("#copyTableQr").onclick=async()=>{try{await navigator.clipboard.writeText(j.url);section.querySelector("#tableQrMessage").textContent="Link kopiert."}catch(e){section.querySelector("#tableQrMessage").textContent="Link konnte nicht kopiert werden."}};
 section.querySelector("#printTableQr").onclick=()=>{const win=window.open("","_blank");if(!win){section.querySelector("#tableQrMessage").textContent="Bitte Pop-ups für den Druck erlauben.";return}const restaurant=esc(j.restaurantName||"Restaurant"),table=esc(j.tableName||t.name),logo=j.logo?'<img class="qrlogo" src="'+esc(j.logo)+'" alt="Restaurantlogo">':"";win.document.write('<!doctype html><html lang="de"><head><meta charset="utf-8"><title>'+restaurant+' · '+table+'</title><style>@page{size:A5 portrait;margin:12mm}*{box-sizing:border-box}body{margin:0;font:17px system-ui;text-align:center;color:#142b42}.poster{border:2px solid #d8e3e8;border-radius:18px;padding:28px 16px;min-height:180mm}.restaurant{font-size:32px;margin:4px 0 14px;overflow-wrap:anywhere}.subtitle{font-size:16px;margin:8px 0 22px}.qrwrap{position:relative;width:260px;height:260px;margin:0 auto}.qrwrap svg{width:100%;height:100%;display:block}.qrlogo{position:absolute;width:48px;height:48px;object-fit:contain;border:5px solid white;border-radius:50%;background:white;top:50%;left:50%;transform:translate(-50%,-50%)}.steps{display:flex;justify-content:space-around;gap:7px;margin:23px 0;font-size:12px;font-weight:700}.steps span{flex:1}.table{font-size:23px;font-weight:900;border:1px solid #d5e1e8;border-radius:12px;display:inline-block;padding:9px 24px;margin-top:10px}@media print{body{-webkit-print-color-adjust:exact;print-color-adjust:exact}}</style></head><body><div class="poster"><h1 class="restaurant">'+restaurant+'</h1><p class="subtitle">Speisekarte öffnen und am Tisch bestellen</p><div class="qrwrap">'+j.svg+logo+'</div><div class="steps"><span>① QR-Code scannen</span><span>② Speisekarte ansehen</span><span>③ Bestellung aufgeben</span></div><div class="table">'+table+'</div></div></body></html>');win.document.close();win.onload=()=>{win.focus();win.print()};};
 section.querySelector("#resetTableQr").onclick=async()=>{if(!confirm("Alten QR-Code ungültig machen? Bereits gedruckte Tischaufsteller müssen ersetzt werden."))return;try{await api("/tables/"+encodeURIComponent(t.id)+"/qr/reset",{method:"POST"});showTableQr(t,host)}catch(e){section.querySelector("#tableQrMessage").textContent=e.message}};
 }catch(e){section.querySelector("#tableQrStatus").textContent=e.message}
 section.scrollIntoView({behavior:"smooth",block:"nearest"});
}

let kitchenBoardSignature="",kitchenPolling=false,kitchenSeenOrders=new Map(),kitchenSoundEnabled=localStorage.getItem("bringness-kitchen-sound")==="yes";
function kitchenChime(){if(!kitchenSoundEnabled)return;try{const C=window.AudioContext||window.webkitAudioContext;if(!C)return;const ctx=new C(),start=ctx.currentTime;for(const [i,freq] of [740,988].entries()){const osc=ctx.createOscillator(),gain=ctx.createGain();osc.type="sine";osc.frequency.value=freq;gain.gain.setValueAtTime(.0001,start+i*.18);gain.gain.exponentialRampToValueAtTime(.14,start+i*.18+.02);gain.gain.exponentialRampToValueAtTime(.0001,start+i*.18+.16);osc.connect(gain).connect(ctx.destination);osc.start(start+i*.18);osc.stop(start+i*.18+.17)}setTimeout(()=>ctx.close().catch(()=>{}),900)}catch(e){console.warn("Küchensignal nicht verfügbar",e)}}
function trackKitchenOrders(restaurantId,orders,notify){const ids=new Set(orders.filter(o=>!["paid","cancelled"].includes(o.status)).map(o=>o.id)),previous=kitchenSeenOrders.get(restaurantId);kitchenSeenOrders.set(restaurantId,ids);if(notify&&previous&&[...ids].some(id=>!previous.has(id)))kitchenChime()}

async function renderOrderBoard(view,restaurantId,prefetched){
 const body=$("moduleBody"),j=prefetched||await api("/orders/list?restaurantId="+encodeURIComponent(restaurantId)),orders=(j.orders||[]).filter(o=>view==="bestellungen"||!["paid","cancelled"].includes(o.status));
 kitchenBoardSignature=JSON.stringify({view,restaurantId,orders});if(view==="kueche")trackKitchenOrders(restaurantId,orders,false);
 const statusNames={open:"Neu",kitchen:"Küche",preparing:"In Zubereitung",ready:"Abholbereit",served:"Serviert",paid:"Bezahlt",cancelled:"Storniert"};
 const buttons=o=>{const next={open:["kitchen","An Küche senden"],kitchen:["preparing","Zubereitung starten"],preparing:["ready","Als fertig markieren"],ready:["served","Als serviert markieren"]}[o.status];return next?'<button class="primary" data-kitchen-next="'+esc(o.id)+'" data-next-status="'+next[0]+'">'+next[1]+'</button>':""};
 body.innerHTML='<div class="kitchenbar"><b>'+orders.length+' '+(view==="kueche"?"aktive Küchenbestellungen":"Bestellungen")+'</b><span class="kitchenautorefresh">● Live · automatisch alle 12 Sek.</span>'+(view==="kueche"?'<button id="kitchenSound" type="button" aria-pressed="'+kitchenSoundEnabled+'">'+(kitchenSoundEnabled?"🔔 Signal an":"🔕 Signal aus")+'</button>':"")+'<button id="refreshOrders" type="button">↻ Aktualisieren</button></div><div class="kitchengrid">'+(orders.map(o=>'<article class="kitchenticket '+esc(o.status)+'"><div class="kitchentickethead"><span class="kitchenstatus">'+esc(statusNames[o.status]||o.status)+'</span><strong>#'+esc(o.id.slice(0,8))+'</strong></div><h3>'+esc(o.table_name||"Theke")+'</h3><p class="muted">'+esc(o.table_area||"")+' · '+(o.source==="qr"?"QR-Bestellung":"Mitarbeiter / Kasse")+'</p><p class="kitchentime">'+new Date(o.created_at).toLocaleString("de-DE")+'</p><div class="kitchenitems">'+(o.items||[]).map(i=>'<div><b>'+esc(i.quantity)+' ×</b> '+esc(i.name)+'</div>').join("")+'</div><div class="kitchenfoot"><strong>'+euro(o.total_cents)+'</strong>'+buttons(o)+'</div></article>').join("")||'<p class="muted">Zurzeit keine Bestellungen.</p>')+'</div><p id="kitchenMessage" role="status"></p>';
 body.querySelector("#refreshOrders").onclick=()=>renderOrderBoard(view,restaurantId);
 if(view==="kueche")body.querySelector("#kitchenSound").onclick=()=>{kitchenSoundEnabled=!kitchenSoundEnabled;localStorage.setItem("bringness-kitchen-sound",kitchenSoundEnabled?"yes":"no");const btn=body.querySelector("#kitchenSound");btn.textContent=kitchenSoundEnabled?"🔔 Signal an":"🔕 Signal aus";btn.setAttribute("aria-pressed",String(kitchenSoundEnabled));if(kitchenSoundEnabled)kitchenChime()};
 body.querySelectorAll("[data-kitchen-next]").forEach(btn=>btn.onclick=async()=>{btn.disabled=true;try{await api("/orders/"+encodeURIComponent(btn.dataset.kitchenNext)+"/status",{method:"PATCH",body:JSON.stringify({status:btn.dataset.nextStatus})});await renderOrderBoard(view,restaurantId);refreshNewOrderBadge()}catch(e){body.querySelector("#kitchenMessage").textContent=e.message;btn.disabled=false}});
}

function updateHeaderClock(){const time=$("headerClockTime"),date=$("headerClockDate");if(!time||!date)return;const now=new Date();time.textContent=new Intl.DateTimeFormat("de-DE",{hour:"2-digit",minute:"2-digit",second:"2-digit",hour12:false}).format(now);date.textContent=new Intl.DateTimeFormat("de-DE",{weekday:"short",day:"2-digit",month:"2-digit",year:"numeric"}).format(now);time.dateTime=now.toISOString()}
updateHeaderClock();setInterval(updateHeaderClock,250);document.addEventListener("visibilitychange",()=>{if(!document.hidden)updateHeaderClock()});

async function refreshActiveOrderBoard(){
 if(kitchenPolling||document.hidden||!token)return;
 const active=document.querySelector("#mainnav button[data-view].active")?.dataset.view;
 if(!["kueche","bestellungen"].includes(active)||!$("moduleBody")||!$("restaurant").value)return;
 kitchenPolling=true;try{const rid=$("restaurant").value,j=await api("/orders/list?restaurantId="+encodeURIComponent(rid));if(document.querySelector("#mainnav button[data-view].active")?.dataset.view!==active||$("restaurant").value!==rid)return;const orders=(j.orders||[]).filter(o=>active==="bestellungen"||!["paid","cancelled"].includes(o.status)),signature=JSON.stringify({view:active,restaurantId:rid,orders});if(active==="kueche")trackKitchenOrders(rid,orders,true);if(signature!==kitchenBoardSignature)await renderOrderBoard(active,rid,j)}catch(e){const msg=$("kitchenMessage");if(msg)msg.textContent="Aktualisierung fehlgeschlagen: "+e.message}finally{kitchenPolling=false}
}
setInterval(refreshActiveOrderBoard,12000);document.addEventListener("visibilitychange",()=>{if(!document.hidden)refreshActiveOrderBoard()});

async function renderRestaurantBranding(restaurantId){
 const body=$("moduleBody"),j=await api("/restaurants/"+encodeURIComponent(restaurantId)+"/branding"),r=j.restaurant,mode=data.restaurants.find(x=>x.id===restaurantId)?.mode==="restaurant"?"restaurant":"counter";
 const waiterData=mode==="restaurant"?await api("/waiters?restaurantId="+encodeURIComponent(restaurantId)).catch(()=>({waiters:[]})):{waiters:[]};
 const assignmentData=mode==="restaurant"?await api("/waiters/assignments?restaurantId="+encodeURIComponent(restaurantId)).catch(()=>({tables:[]})):{tables:[]};
 const areaData=mode==="restaurant"?await api("/waiters/areas?restaurantId="+encodeURIComponent(restaurantId)).catch(()=>({areas:[]})):{areas:[]};
 body.innerHTML=(mode==="restaurant"?'<div class="modulecard brandingcard"><h3>Kellner & Mitarbeiterzugänge</h3><p>Jeder Kellner erhält einen eigenen Zugang nur für den Restaurantservice. Das Erstpasswort muss beim ersten Login geändert werden. <a href="/service/" target="_blank" rel="noopener">Kellner-Anmeldung öffnen ↗</a></p><form id="waiterAccountForm"><label>Name<input id="waiterAccountName" required minlength="2" maxlength="100"></label><label>Login-E-Mail<input id="waiterAccountEmail" type="email" required></label><label>Erstpasswort (mindestens 12 Zeichen)<input id="waiterAccountPassword" type="password" required minlength="12" autocomplete="new-password"></label><button class="primary" type="submit">Kellnerkonto anlegen</button></form><p id="waiterAccountMessage" role="status"></p><h3>Bereichszuweisung</h3><p>Mit einer Auswahl werden alle bestehenden Tische des Bereichs dem Kellner zugewiesen. Einzelne Tische kannst du darunter weiterhin abweichend zuordnen.</p><div class="waiterareas">'+areaData.areas.map(a=>'<div class="row" style="display:flex;gap:12px;align-items:center;justify-content:space-between;margin:10px 0"><label for="area-'+esc(a.area)+'">'+esc(a.area)+' ('+a.table_count+' Tische)</label><select id="area-'+esc(a.area)+'" data-assign-area="'+esc(a.area)+'"><option value="">Kein Kellner</option>'+waiterData.waiters.filter(w=>w.active).map(w=>'<option value="'+esc(w.id)+'" '+(a.waiter_ids&&a.waiter_ids.length===1&&a.assigned_count===a.table_count&&a.waiter_ids[0]===w.id?"selected":"")+'>'+esc(w.display_name)+'</option>').join("")+'</select></div>').join("")+'</div><h3>Tischzuweisung</h3><p>Nur zugewiesene Tische erscheinen im Kellnerkonto. Nicht zugewiesene Tische bleiben für den Inhaber sichtbar.</p><div class="waiterassignments">'+assignmentData.tables.map(t=>'<div class="row" style="display:flex;gap:12px;align-items:center;justify-content:space-between;margin:10px 0"><label for="assign-'+esc(t.id)+'">'+esc(t.name)+(t.area?' · '+esc(t.area):"")+'</label><select id="assign-'+esc(t.id)+'" data-assign-table="'+esc(t.id)+'"><option value="">Kein Kellner</option>'+waiterData.waiters.filter(w=>w.active).map(w=>'<option value="'+esc(w.id)+'" '+(w.id===t.waiter_employee_id?"selected":"")+'>'+esc(w.display_name)+'</option>').join("")+'</select></div>').join("")+'</div><div class="waiterlist">'+waiterData.waiters.map(w=>'<div class="modulecard"><b>'+esc(w.display_name)+'</b><p class="muted">'+esc(w.email)+' · '+(w.active?"Aktiv":w.status==="disabled"?"Deaktiviert":"Noch nicht freigeschaltet")+'</p>'+(w.status!=="disabled"?'<button type="button" data-disable-waiter="'+esc(w.id)+'">Zugang sperren</button>':"")+'</div>').join("")+'</div></div>':"")+'<div class="modulecard brandingcard"><h3>Betriebsart</h3><p>Restaurant aktiviert Tische, Bestellungen und Küche. Café, Imbiss & Co. nutzt nur die Kasse. Die Auswahl gilt für diesen Betrieb.</p><form id="businessModeForm"><label for="businessMode">Betriebsart</label><select id="businessMode"><option value="counter" '+(mode==="counter"?"selected":"")+'>Café, Imbiss & Co. – nur Kasse</option><option value="restaurant" '+(mode==="restaurant"?"selected":"")+'>Restaurant – Kasse, Tische, Bestellungen und Küche</option></select><button class="primary" type="submit">Betriebsart speichern</button></form><p id="businessModeMessage" role="status"></p></div><div class="modulecard brandingcard"><h3>Restaurantname und QR-Logo</h3><p>Der Restaurantname erscheint oben auf dem gedruckten Tisch-QR. Das optionale Logo sitzt in der Mitte des QR-Codes.</p><form id="brandingForm"><label>Restaurantname<input id="brandingName" maxlength="120" required value="'+esc(r.name)+'"></label><label>Restaurantlogo (PNG, JPEG oder WebP, max. 150 KB)<input id="brandingLogo" type="file" accept="image/png,image/jpeg,image/webp"></label><div id="brandingPreview">'+(r.logo_data?'<img alt="Aktuelles Restaurantlogo" src="'+esc(r.logo_data)+'">':'<span>Kein Logo hinterlegt</span>')+'</div><label><input id="brandingRemove" type="checkbox"> Bestehendes Logo entfernen</label><button class="primary">Änderungen speichern</button></form><p id="brandingMessage" role="status"></p></div>';
 if(mode==="restaurant"&&$("waiterAccountForm")){$("waiterAccountForm").onsubmit=async e=>{e.preventDefault();const msg=$("waiterAccountMessage");try{await api("/waiters",{method:"POST",body:JSON.stringify({restaurantId,name:$("waiterAccountName").value,email:$("waiterAccountEmail").value,password:$("waiterAccountPassword").value})});await renderRestaurantBranding(restaurantId)}catch(err){msg.textContent=err.message}};body.querySelectorAll("[data-assign-area]").forEach(sel=>sel.onchange=async()=>{sel.disabled=true;try{const j=await api("/waiters/areas",{method:"PUT",body:JSON.stringify({restaurantId,area:sel.dataset.assignArea,waiterId:sel.value||null})});await renderRestaurantBranding(restaurantId);$("waiterAccountMessage").textContent=j.updatedTables+" Tische im Bereich „"+j.area+"“ zugewiesen."}catch(err){$("waiterAccountMessage").textContent=err.message;await renderRestaurantBranding(restaurantId)}finally{sel.disabled=false}});body.querySelectorAll("[data-assign-table]").forEach(sel=>sel.onchange=async()=>{sel.disabled=true;try{await api("/waiters/assignments",{method:"PUT",body:JSON.stringify({restaurantId,tableId:sel.dataset.assignTable,waiterId:sel.value||null})});$("waiterAccountMessage").textContent="Tischzuweisung gespeichert."}catch(err){$("waiterAccountMessage").textContent=err.message;await renderRestaurantBranding(restaurantId)}finally{sel.disabled=false}});body.querySelectorAll("[data-disable-waiter]").forEach(btn=>btn.onclick=async()=>{if(!confirm("Kellnerzugang sofort sperren?"))return;try{await api("/waiters/"+encodeURIComponent(btn.dataset.disableWaiter)+"/disable",{method:"POST"});await renderRestaurantBranding(restaurantId)}catch(err){$("waiterAccountMessage").textContent=err.message}})}
 body.querySelector("#businessModeForm").onsubmit=async e=>{e.preventDefault();const msg=$("businessModeMessage"),mode=$("businessMode").value;try{const j=await api("/restaurants/"+encodeURIComponent(restaurantId)+"/mode",{method:"PUT",body:JSON.stringify({mode})});const local=data.restaurants.find(r=>r.id===restaurantId);if(local)local.mode=j.restaurant.mode;applyBusinessMode();msg.textContent="Betriebsart gespeichert. Die Navigation wurde angepasst."}catch(err){msg.textContent=err.message}};
 body.querySelector("#brandingForm").onsubmit=async e=>{e.preventDefault();const msg=body.querySelector("#brandingMessage"),file=body.querySelector("#brandingLogo").files[0];if(file&&file.size>150000){msg.textContent="Logo ist größer als 150 KB.";return}if(file&&!["image/png","image/jpeg","image/webp"].includes(file.type)){msg.textContent="Bitte PNG, JPEG oder WebP verwenden.";return}let logo=body.querySelector("#brandingRemove").checked?null:r.logo_data||null;if(file){logo=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(file)})}try{const updated=await api("/restaurants/"+encodeURIComponent(restaurantId)+"/branding",{method:"PUT",body:JSON.stringify({name:body.querySelector("#brandingName").value.trim(),logo})});const opt=$("restaurant").selectedOptions[0];if(opt)opt.textContent=updated.restaurant.name;msg.textContent="Restaurantname und Logo gespeichert. Neue QR-Ausdrucke verwenden das aktuelle Branding.";await renderRestaurantBranding(restaurantId)}catch(err){msg.textContent=err.message}};
}

let guestPresencePolling=false;
async function refreshGuestPresence(){const el=$("guestPresenceCount"),restaurant=$("restaurant");if(!el||!restaurant||!token||guestPresencePolling)return;const rid=restaurant.value;if(!rid){el.textContent="–";return}guestPresencePolling=true;try{const j=await api("/guest/presence/count?restaurantId="+encodeURIComponent(rid));if(restaurant.value===rid){el.textContent=String(j.count);$("guestPresence").title=j.count+" QR-Gäste aktuell aktiv (letzte 90 Sekunden)"}}catch(e){el.textContent="–";$("guestPresence").title="QR-Gäste derzeit nicht abrufbar"}finally{guestPresencePolling=false}}
setInterval(()=>{if(!document.hidden)refreshGuestPresence()},15000);document.addEventListener("visibilitychange",()=>{if(!document.hidden)refreshGuestPresence()});$("restaurant")?.addEventListener("change",refreshGuestPresence);refreshGuestPresence();

async function refreshTableDashboard(){
 if(tableDashboardPolling||document.hidden||!token||!tableDashboardState)return;
 const rid=tableDashboardState.restaurantId,active=document.querySelector("#mainnav button[data-view].active")?.dataset.view;
 if(active!=="tische"||$("restaurant")?.value!==rid||!$("tableSections"))return;
 tableDashboardPolling=true;try{const j=await api("/tables?restaurantId="+encodeURIComponent(rid)),snapshot=JSON.stringify(j.tables||[]);if(snapshot!==tableDashboardSnapshot&&document.querySelector("#mainnav button[data-view].active")?.dataset.view==="tische"&&$("restaurant")?.value===rid){await renderTableDashboard(rid)}}catch(e){console.warn("Tischstatus konnte nicht aktualisiert werden",e)}finally{tableDashboardPolling=false}
}
setInterval(refreshTableDashboard,12000);document.addEventListener("visibilitychange",()=>{if(!document.hidden)refreshTableDashboard()});

let newOrderBadgePolling=false;
async function refreshNewOrderBadge(){const badge=$("newOrderBadge"),kitchenBadge=$("kitchenOrderBadge"),restaurant=$("restaurant");if(!badge||!restaurant||!token||newOrderBadgePolling)return;const rid=restaurant.value;if(!rid){badge.hidden=true;if(kitchenBadge)kitchenBadge.hidden=true;return}newOrderBadgePolling=true;try{const j=await api("/orders/new-count?restaurantId="+encodeURIComponent(rid));if(restaurant.value!==rid)return;const count=Number(j.count)||0;badge.textContent=count>99?"99+":String(count);badge.hidden=count===0;badge.title=count+" neue Tisch- und QR-Bestellungen";if(kitchenBadge){kitchenBadge.textContent=badge.textContent;kitchenBadge.hidden=count===0;kitchenBadge.title=count+" neue Bestellungen für die Küche"}}catch(e){badge.hidden=true;if(kitchenBadge)kitchenBadge.hidden=true}finally{newOrderBadgePolling=false}}
setInterval(()=>{if(!document.hidden)refreshNewOrderBadge()},10000);document.addEventListener("visibilitychange",()=>{if(!document.hidden)refreshNewOrderBadge()});$("restaurant")?.addEventListener("change",refreshNewOrderBadge);refreshNewOrderBadge();

function isRestaurantMode(){return data?.restaurants?.find(r=>r.id===$("restaurant")?.value)?.mode==="restaurant"}
function applyBusinessMode(){const restaurant=isRestaurantMode();document.querySelectorAll('#mainnav [data-view="tische"],#mainnav [data-view="bestellungen"],#mainnav [data-view="kueche"]').forEach(b=>{b.hidden=!restaurant;b.style.display=restaurant?"":"none"});const guest=$("guestPresence");if(guest)guest.style.display=restaurant?"":"none";if(!restaurant){const active=document.querySelector('#mainnav button[data-view].active')?.dataset.view;if(["tische","bestellungen","kueche"].includes(active))showModule("kasse")}}
